import useSWRImmutable from 'swr/immutable'

// Natural Earth boundaries (public domain), generated by scripts/build-geo.sh into public/geo/.
export type Polygonal = { type: 'Polygon'; coordinates: number[][][] } | { type: 'MultiPolygon'; coordinates: number[][][][] }
export type CountryFeature = { type: 'Feature'; properties: { ADM0_A3: string; NAME: string; LABEL_X: number; LABEL_Y: number }; geometry: Polygonal }
export type StateFeature = { type: 'Feature'; properties: { adm0_a3: string; name: string; latitude: number; longitude: number }; geometry: Polygonal }
type Collection<F> = { features: F[] }

async function fetchJson<T>(url: string): Promise<T> {
  const response = await fetch(url)
  if (!response.ok) throw new Error(`${url}: HTTP ${response.status}`)
  return response.json()
}

// Static files: SWR dedupes by key, so the globe, the selects and the 2D map share one request.
export const useCountries = () => useSWRImmutable<Collection<CountryFeature>>('/geo/countries.json', fetchJson)
export const useStates = (country?: string) => useSWRImmutable<Collection<StateFeature>>(country ? `/geo/admin1/${country}.json` : null, fetchJson)

const KM_PER_DEGREE = 111.32
const rings = (geometry: Polygonal) => geometry.type === 'Polygon' ? geometry.coordinates : geometry.coordinates.flat()

// ponytail: equirectangular with x scaled by cos(mid-latitude). Fine for a state or a country; the scale bar is
// exact only at the mid-latitude, so very tall countries (Chile, Russia) drift. Swap in d3-geo if that matters.
export function fitProjection(target: Polygonal, width: number, height: number, padding = 16) {
  const points = rings(target).flat()
  // Antimeridian: a shape spanning more than 180° (Russia, Fiji, Alaska) is drawn with western longitudes shifted by +360.
  const wraps = Math.max(...points.map(([lon]) => lon)) - Math.min(...points.map(([lon]) => lon)) > 180
  const unwrap = (lon: number) => wraps && lon < 0 ? lon + 360 : lon
  const lons = points.map(([lon]) => unwrap(lon))
  const lats = points.map(([, lat]) => lat)
  const [minLon, maxLon, minLat, maxLat] = [Math.min(...lons), Math.max(...lons), Math.min(...lats), Math.max(...lats)]
  const xFactor = Math.cos(((minLat + maxLat) / 2) * Math.PI / 180)
  const scale = Math.min((width - 2 * padding) / Math.max((maxLon - minLon) * xFactor, 1e-6), (height - 2 * padding) / Math.max(maxLat - minLat, 1e-6))
  const [centerLon, centerLat] = [(minLon + maxLon) / 2, (minLat + maxLat) / 2]
  const toXY = (lon: number, lat: number): [number, number] => [width / 2 + (lon - centerLon) * xFactor * scale, height / 2 - (lat - centerLat) * scale]
  const project = (lon: number, lat: number): [number, number] => toXY(unwrap(lon), lat)
  // Map coordinates back to [lon, lat], with longitude wrapped into [-180, 180).
  const invert = (x: number, y: number): [number, number] => {
    const lon = centerLon + (x - width / 2) / (xFactor * scale)
    return [((lon + 540) % 360) - 180, Math.max(-90, Math.min(90, centerLat - (y - height / 2) / scale))]
  }
  // Shift whole rings, never single vertices: a ring that crosses 0° (France, Algeria…) must not have its
  // western half moved +360°, or it stretches into a band across the map. Natural Earth splits rings at
  // ±180°, so "entirely west of 0°" is exactly the set of rings that belongs on the far side of the wrap.
  const path = (geometry: Polygonal) => rings(geometry).map((ring) => {
    const shift = wraps && Math.max(...ring.map(([lon]) => lon)) < 0 ? 360 : 0
    return `M${ring.map(([lon, lat]) => toXY(lon + shift, lat).map((value) => value.toFixed(1)).join(',')).join('L')}Z`
  }).join('')
  // The whole planet in map units (wrapped maps reach 360°), used to keep panning from losing the world.
  const [x0, y0] = toXY(-180, 90)
  const [x1, y1] = toXY(wraps ? 360 : 180, -90)
  return { project, invert, path, kmPerPixel: KM_PER_DEGREE / scale, world: { x0, y0, x1, y1 } }
}

// Largest 1/2/5 × 10ⁿ value that fits under `maxKm`, for a scale bar.
export function niceKm(maxKm: number) {
  const power = 10 ** Math.floor(Math.log10(maxKm))
  return [5, 2, 1].map((step) => step * power).find((value) => value <= maxKm) ?? power
}
